    def __init__(self) -> None:
        super().__init__()
        self.sample_input: List[pathlib.Path] = []
        self.fastq: List[pathlib.Path] = []
        self.readgroups: List[str] = []
        self.model_bundle: Optional[pathlib.Path] = None
        self.dbsnp: Optional[pathlib.Path] = None
        self.bed: Optional[pathlib.Path] = None
        self.haploid_bed: Optional[pathlib.Path] = None
        self.cnv_excluded_regions: Optional[pathlib.Path] = None
        self.gvcf = False
        self.tech = "HiFi"
        self.skip_small_variants = False
        self.skip_svs = False
        self.skip_mosdepth = False
        self.skip_cnv = False
        self.align = False
        self.input_ref: Optional[pathlib.Path] = None
        self.pop_vcf: Optional[pathlib.Path] = None
        self.fastq_taglist = "*"
        self.bam_format = False
        self.minimap2_args = "-YL"
        self.util_sort_args = (
            "--cram_write_options version=3.0,compressor=rans"
        )
        self.repeat_model: Optional[pathlib.Path] = None
        self.skip_pop_vcf_id_check = False
        self.use_pbsv = False

    def validate(self) -> None:
        # uniquify pipeline attributes
        self.lr_aln = self.sample_input
        self.lr_input_ref = self.input_ref
        del self.sample_input

        # validate
        if not (self.lr_aln or self.fastq):
            self.logger.error(
                "Please supply either the `--sample_input` or `--fastq` and "
                "`--readgroups` arguments"
            )
            sys.exit(2)
        if len(self.fastq) != len(self.readgroups):
            self.logger.error(
                "The number of readgroups does not equal the number of fastq "
                "files"
            )
            sys.exit(2)
        for rg in self.readgroups:
            try:
                parse_rg_line(rg.replace(r"\t", "\t"))
            except ValueError as e:
                self.logger.error("Invalid --readgroups value '%s': %s", rg, e)
                sys.exit(2)
        self.validate_output_vcf()
        if self.tech.upper() == "ONT":
            self.logger.info("Skipping CNV calling with ONT data")
            self.skip_cnv = True

        if not library_preloaded("libjemalloc.so"):
            self.logger.warning(
                "jemalloc is recommended, but is not preloaded. See "
                "https://support.sentieon.com/appnotes/jemalloc/"
            )

        if not self.cnv_excluded_regions and not self.skip_cnv:
            self.logger.warning(
                "Excluded regions are recommended for CNV calling. Please "
                "supply them with the `--cnv_excluded_regions` argument"
            )

        if not self.skip_small_variants:
            if self.haploid_bed and not self.bed:
                self.logger.error(
                    "Please supply a BED file of diploid regions to "
                    "distinguish haploid and diploid regions of the genome."
                )
                sys.exit(2)
            if not self.bed:
                self.logger.warning(
                    "A BED file is recommended to restrict variant calling to "
                    "diploid regions of the genome."
                )

        self.fai_data = parse_fai(pathlib.Path(str(self.reference) + ".fai"))
        self.pop_vcf_contigs: Dict[str, Optional[int]] = {}
        if self.pop_vcf:
            self.pop_vcf_contigs = vcf_contigs(self.pop_vcf, self.dry_run)
            self.logger.debug("VCF contigs are: %s", self.pop_vcf_contigs)
        self.shards = determine_shards_from_fai(
            self.fai_data, 10 * 1000 * 1000
        )
        self.validate_bundle()

    def validate_bundle(self):
        """Validate the model bundle"""
        # Validate bundle members
        bundle_members: Set[str] = set(
            ar_load(str(self.model_bundle))
        )  # type: ignore
        expected_members = {
            "diploid_hp_model",
            "diploid_model",
            "diploid_model_unphased",
            "gvcf_model",
            "haploid_hp_model",
            "haploid_model",
            "longreadsv.model",
            "minimap2.model",
        }
        missing_members = expected_members - bundle_members
        if missing_members:
            self.logger.error(
                "The model bundle is missing expected files: %s",
                missing_members,
            )
            sys.exit(2)

        # Validate the bundle_info.json
        bundle_info_bytes = ar_load(
            str(self.model_bundle) + "/bundle_info.json"
        )
        if isinstance(bundle_info_bytes, list):
            bundle_info_bytes = b"{}"
        bundle_info = json.loads(bundle_info_bytes.decode())

        # Without a bundle_info.json - we do not expect a pop VCF
        if not bundle_info:
            if self.pop_vcf:
                self.logger.error(
                    "The model bundle does not require a population VCF. "
                    "Please use this model bundle files without the "
                    "`--pop_vcf` argument."
                )
                sys.exit(2)
            return

        try:
            req_version = packaging.version.Version(
                bundle_info["minScriptVersion"]
            )
            bundle_pipeline = bundle_info["pipeline"]
            bundle_tech = bundle_info["platform"]
        except KeyError:
            self.logger.error(
                "The model bundle does not have the expected attributes"
            )
            sys.exit(2)

        # Check package version
        if req_version > packaging.version.Version(__version__):
            self.logger.error(
                "The model bundle requires version %s or later of the "
                "sentieon-cli.",
                req_version,
            )
            sys.exit(2)

        # Check the pipeline
        if bundle_pipeline != "DNAscope LongRead":
            self.logger.error("The model bundle is for a different pipeline.")
            sys.exit(2)

        # Check the tech
        if bundle_tech.upper() != self.tech.upper():
            self.logger.error(
                "Mismatch between the bundle tech and the `--tech` argument. "
                "Bundle uses %s while `--tech` has %s",
                bundle_tech,
                self.tech,
            )

        # Check the pop VCF
        if "SentieonVcfID" in bundle_info:
            if not self.pop_vcf:
                self.logger.error(
                    "The model bundle requires a population VCF. Please "
                    "contact Sentieon support to obtain the correct "
                    "population VCF for this model bundle, or use a "
                    "different model bundle."
                )
                sys.exit(2)
            if self.skip_pop_vcf_id_check:
                return
            current_vcf_id = vcf_id(self.pop_vcf)
            if current_vcf_id != bundle_info["SentieonVcfID"]:
                self.logger.error(
                    "The population VCF provided does not match the "
                    "population VCF required by the model bundle. "
                    "Expected: %s, Found: %s",
                    bundle_info["SentieonVcfID"],
                    current_vcf_id,
                )
                sys.exit(2)

        if self.pop_vcf and "SentieonVcfID" not in bundle_info:
            self.logger.error(
                "The model bundle does not require a population VCF. Please "
                "use this model bundle files without the `--pop_vcf` argument."
            )
            sys.exit(2)

    def configure(self) -> None:
        pass

    def build_dag(self) -> DAG:
        self.logger.info("Building the DAG")
        dag = DAG()

        sample_input = self.lr_aln
        realign_jobs: Set[Job] = set()
        if self.align:
            sample_input, realign_jobs = self.lr_align_inputs()
            for job in realign_jobs:
                dag.add_job(job)
        aligned_fastq, align_jobs = self.lr_align_fastq()
        sample_input.extend(aligned_fastq)
        for job in align_jobs:
            dag.add_job(job)

        if not self.skip_mosdepth:
            mosdepth_jobs = self.mosdepth(sample_input)
            for job in mosdepth_jobs:
                dag.add_job(job, realign_jobs.union(align_jobs))

        if self.use_pbsv or not self.skip_cnv:
            merged_bam, merge_job = self.merge_input_files(sample_input)
            dag.add_job(merge_job, realign_jobs.union(align_jobs))

            if self.use_pbsv:
                pbsv_discover, pbsv_call = self.pbsv(merged_bam)
                dag.add_job(pbsv_discover, {merge_job})
                dag.add_job(pbsv_call, {pbsv_discover})

            if not self.skip_cnv:
                hificnv_job = self.hificnv(merged_bam)
                if hificnv_job:
                    dag.add_job(hificnv_job, {merge_job})

        if not self.skip_small_variants:
            cv = self.lr_call_variants(sample_input)
            dag.add_job(cv.first_calling_job, realign_jobs.union(align_jobs))

            first_ma_deps = {cv.first_calling_job}
            if cv.diploid_transfer_jobs and cv.diploid_concat_job:
                for job in cv.diploid_transfer_jobs:
                    dag.add_job(job, {cv.first_calling_job})
                dag.add_job(
                    cv.diploid_concat_job, set(cv.diploid_transfer_jobs)
                )
                first_ma_deps.add(cv.diploid_concat_job)

            dag.add_job(cv.first_modelapply_job, first_ma_deps)
            dag.add_job(cv.phaser_job, {cv.first_modelapply_job})

            haploid_patch_deps: Set[Job] = set()
            if cv.bcftools_subset_phased_job:
                dag.add_job(cv.bcftools_subset_phased_job, {cv.phaser_job})
                haploid_patch_deps.add(cv.bcftools_subset_phased_job)

            subtract_deps: Set[Job] = {cv.phaser_job}
            if cv.fai_to_bed_job:
                dag.add_job(cv.fai_to_bed_job)
                subtract_deps.add(cv.fai_to_bed_job)
            dag.add_job(cv.bcftools_subtract_job, subtract_deps)
            dag.add_job(
                cv.bcftools_subset_unphased_job,
                {cv.bcftools_subtract_job},
            )

            second_pass_deps: Set[Job] = {cv.phaser_job}
            calling_unphased_deps: Set[Job] = {cv.bcftools_subtract_job}
            haploid_calling_deps: Set[Job] = set()
            if cv.repeatmodel_job:
                dag.add_job(cv.repeatmodel_job, {cv.phaser_job})
                second_pass_deps.add(cv.repeatmodel_job)
                calling_unphased_deps.add(cv.repeatmodel_job)
                haploid_calling_deps.add(cv.repeatmodel_job)

            merge_deps: Set[Job] = set()
            for job in cv.second_calling_job:
                dag.add_job(job, second_pass_deps)
                haploid_patch_deps.add(job)
            dag.add_job(cv.haploid_patch_job, haploid_patch_deps)

            second_ma_deps = {cv.haploid_patch_job}
            if cv.patch_transfer_jobs:  # pop_vcf
                for patch_transfer_hap, patch_concat in zip(
                    cv.patch_transfer_jobs, cv.patch_concat_jobs
                ):
                    for job in patch_transfer_hap:
                        dag.add_job(job, {cv.haploid_patch_job})
                    dag.add_job(patch_concat, set(patch_transfer_hap))
                    second_ma_deps.add(patch_concat)

            for job in cv.second_modelapply_job:
                dag.add_job(job, second_ma_deps)
                merge_deps.add(job)

            dag.add_job(cv.calling_unphased_job, calling_unphased_deps)
            dag.add_job(
                cv.diploid_patch_job,
                {
                    cv.bcftools_subset_unphased_job,
                    cv.calling_unphased_job,
                },
            )

            unphased_ma_deps = {cv.diploid_patch_job}
            if cv.unphased_transfer_jobs and cv.unphased_concat_job:  # pop_vcf
                for job in cv.unphased_transfer_jobs:
                    dag.add_job(job, {cv.diploid_patch_job})
                dag.add_job(
                    cv.unphased_concat_job, set(cv.unphased_transfer_jobs)
                )
                unphased_ma_deps.add(cv.unphased_concat_job)

            dag.add_job(cv.modelapply_unphased_job, unphased_ma_deps)
            merge_deps.add(cv.modelapply_unphased_job)
            dag.add_job(cv.merge_job, merge_deps)

            if cv.gvcf_combine_job:
                dag.add_job(cv.gvcf_combine_job, {cv.merge_job})

            if (
                cv.haploid_calling_job
                and cv.haploid_patch2_job
                and cv.haploid_concat_job
            ):
                dag.add_job(cv.haploid_calling_job, haploid_calling_deps)
                dag.add_job(
                    cv.haploid_patch2_job,
                    {cv.haploid_calling_job},
                )
                dag.add_job(
                    cv.haploid_concat_job,
                    {cv.haploid_patch2_job, cv.merge_job},
                )

                if (
                    cv.haploid_gvcf_combine_job
                    and cv.haploid_gvcf_concat_job
                    and cv.gvcf_combine_job
                ):
                    dag.add_job(
                        cv.haploid_gvcf_combine_job,
                        {cv.haploid_patch2_job},
                    )
                    dag.add_job(
                        cv.haploid_gvcf_concat_job,
                        {
                            cv.haploid_gvcf_combine_job,
                            cv.gvcf_combine_job,
                        },
                    )

        if not self.skip_svs:
            longreadsv_job = self.call_svs(sample_input)
            dag.add_job(longreadsv_job, realign_jobs.union(align_jobs))

        return dag

    def lr_align_inputs(self) -> Tuple[List[pathlib.Path], Set[Job]]:
        """
        Align reads to the reference genome using minimap2
        """
        if not self.output_vcf:
            self.logger.error("output_vcf is required")
            sys.exit(2)
        if not self.reference:
            self.logger.error("reference is required")
            sys.exit(2)
        if not self.model_bundle:
            self.logger.error("model_bundle is required")
            sys.exit(2)
        if not self.skip_version_check:
            for cmd, min_version in ALN_MIN_VERSIONS.items():
                if not check_version(cmd, min_version):
                    sys.exit(2)

        res: List[pathlib.Path] = []
        suffix = "bam" if self.bam_format else "cram"
        sample_name = self.output_vcf.name.replace(".vcf.gz", "")
        realign_jobs = set()
        for i, input_aln in enumerate(self.lr_aln):
            out_aln = pathlib.Path(
                str(self.output_vcf).replace(
                    ".vcf.gz", f"_mm2_sorted_{i}.{suffix}"
                )
            )
            rg_lines = cmds.get_rg_lines(
                input_aln,
                self.dry_run,
            )

            realign_jobs.add(
                Job(
                    cmds.cmd_samtools_fastq_minimap2(
                        out_aln,
                        input_aln,
                        self.reference,
                        self.model_bundle,
                        self.cores,
                        rg_lines,
                        sample_name,
                        self.lr_input_ref,
                        self.fastq_taglist,
                        self.minimap2_args,
                        self.util_sort_args,
                    ),
                    f"bam-realign-{i}",
                    self.cores,
                )
            )
            res.append(out_aln)
        return (res, realign_jobs)

    def lr_align_fastq(self) -> Tuple[List[pathlib.Path], Set[Job]]:
        """
        Align fastq to the reference genome using minimap2
        """
        if not self.reference:
            self.logger.error("reference is required")
            sys.exit(2)
        if not self.model_bundle:
            self.logger.error("model_bundle is required")
            sys.exit(2)
        res: List[pathlib.Path] = []
        if self.fastq is None and self.readgroups is None:
            return (res, set())

        if not self.skip_version_check:
            for cmd, min_version in FQ_MIN_VERSIONS.items():
                if not check_version(cmd, min_version):
                    sys.exit(2)

        unzip = "igzip"
        if not shutil.which(unzip):
            self.logger.warning(
                "igzip is recommended for decompression, but is not "
                "available. Falling back to gzip."
            )
            unzip = "gzip"

        suffix = "bam" if self.bam_format else "cram"
        align_jobs = set()
        for i, (fq, rg) in enumerate(zip(self.fastq, self.readgroups)):
            out_aln = pathlib.Path(
                str(self.output_vcf).replace(
                    ".vcf.gz", f"_mm2_sorted_fq_{i}.{suffix}"
                )
            )
            align_jobs.add(
                Job(
                    cmds.cmd_fastq_minimap2(
                        out_aln,
                        fq,
                        rg,
                        self.reference,
                        self.model_bundle,
                        self.cores,
                        unzip,
                        self.minimap2_args,
                        self.util_sort_args,
                    ),
                    "align-{i}",
                    self.cores,
                )
            )
            res.append(out_aln)
        return (res, align_jobs)

    def mosdepth(self, sample_input: List[pathlib.Path]) -> Set[Job]:
        """Run mosdepth for QC"""

        if not self.skip_version_check:
            if not all(
                [
                    check_version(cmd, min_version)
                    for (cmd, min_version) in MOSDEPTH_MIN_VERSIONS.items()
                ]
            ):
                self.logger.warning(
                    "Skipping mosdepth. mosdepth version %s or later "
                    "not found",
                    MOSDEPTH_MIN_VERSIONS["mosdepth"],
                )
                return set()

        mosdepth_jobs = set()
        for i, input_file in enumerate(sample_input):
            mosdepth_dir = pathlib.Path(
                str(self.output_vcf).replace(".vcf.gz", f"_mosdepth_{i}")
            )
            mosdepth_jobs.add(
                Job(
                    cmds.cmd_mosdepth(
                        input_file,
                        mosdepth_dir,
                        fasta=self.reference,
                        threads=self.cores,
                    ),
                    f"mosdepth-{i}",
                    0,  # Run in background
                )
            )
        return mosdepth_jobs

    def merge_input_files(
        self, sample_input: List[pathlib.Path]
    ) -> Tuple[pathlib.Path, Job]:
        """
        Merge the aligned reads into a single BAM
        """
        if not self.skip_version_check:
            for cmd, min_version in MERGE_MIN_VERSIONS.items():
                if not check_version(cmd, min_version):
                    sys.exit(2)

        # Merge the sample_input into a single BAM
        merged_bam = self.tmp_dir.joinpath("longread_merged.bam")
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
            input=sample_input,
        )
        driver.add_algo(ReadWriter(merged_bam))
        merge_job = Job(
            Pipeline(Command(*driver.build_cmd())),
            "merge-bam",
            0,
        )
        return (merged_bam, merge_job)

    def pbsv(
        self,
        merged_bam: pathlib.Path,
    ) -> Tuple[Job, Job]:
        """
        Call SVs with pbsv
        """
        if not self.skip_version_check:
            for cmd, min_version in PBSV_MIN_VERSIONS.items():
                if not check_version(cmd, min_version):
                    sys.exit(2)

        # pbsv discover
        pbsv_discover_fn = str(self.output_vcf).replace(
            ".vcf.gz",
            ".pbsv_discover.svsig.gz",
        )
        pbsv_discover = Job(
            Pipeline(
                Command(
                    "pbsv",
                    "discover",
                    "--hifi",
                    str(merged_bam),
                    pbsv_discover_fn,
                )
            ),
            "pbsv-discover",
            0,
        )

        # pbsv call
        pbsv_call_fn = str(self.output_vcf).replace(".vcf.gz", ".pbsv.vcf")
        call_cmd = [
            "pbsv",
            "call",
            "-j",
            str(self.cores),
            str(self.reference),
            pbsv_discover_fn,
            pbsv_call_fn,
        ]
        pbsv_call = Job(
            Pipeline(Command(*call_cmd)),
            "pbsv-call",
            self.cores,
        )
        return (pbsv_discover, pbsv_call)

    def hificnv(
        self,
        merged_bam: pathlib.Path,
    ) -> Optional[Job]:
        """
        Call CNVs with HiFiCNV
        """
        if not self.skip_version_check:
            for cmd, min_version in HIFICNV_MIN_VERSIONS.items():
                if not check_version(cmd, min_version):
                    self.logger.warning(
                        "Skipping hificnv. hificnv version %s or later not "
                        "found",
                        HIFICNV_MIN_VERSIONS["hificnv"],
                    )
                    return None

        hifi_cnv_fn = str(self.output_vcf).replace(".vcf.gz", ".hificnv")
        hificnv_cmd = [
            "hificnv",
            "--bam",
            str(merged_bam),
            "--ref",
            str(self.reference),
            "--threads",
            str(self.cores),
            "--output-prefix",
            hifi_cnv_fn,
        ]
        if self.cnv_excluded_regions:
            hificnv_cmd.extend(["--exclude", str(self.cnv_excluded_regions)])
        hificnv_job = Job(
            Pipeline(Command(*hificnv_cmd)), "hificnv", self.cores
        )
        return hificnv_job

    def lr_call_variants(
        self,
        sample_input: List[pathlib.Path],
    ) -> LRCallVariantsResult:
        """
        Call SNVs and indels using the DNAscope LongRead pipeline
        """
        if not self.model_bundle:
            self.logger.error("model_bundle is required")
            sys.exit(2)
        if not self.reference:
            self.logger.error("reference is required")
            sys.exit(2)
        if not self.output_vcf:
            self.logger.error("output_vcf is required")
            sys.exit(2)
        if not self.skip_version_check:
            for check_cmd, min_version in TOOL_MIN_VERSIONS.items():
                if not check_version(check_cmd, min_version):
                    sys.exit(2)

        transfer_xargs = (
            self.tmp_dir,
            self.shards,
            self.pop_vcf_contigs,
            self.fai_data,
            self.dry_run,
            self.cores,
        )

        # First pass - diploid calling
        diploid_gvcf_fn = self.tmp_dir.joinpath("out_diploid.g.vcf.gz")
        diploid_tmp_vcf = self.tmp_dir.joinpath("out_diploid_tmp.vcf.gz")
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
            input=sample_input,
            interval=self.bed,
        )
        if self.gvcf:
            driver.add_algo(
                DNAscope(
                    diploid_gvcf_fn,
                    dbsnp=self.dbsnp,
                    emit_mode="gvcf",
                    model=self.model_bundle.joinpath("gvcf_model"),
                )
            )
        driver.add_algo(
            DNAscope(
                diploid_tmp_vcf,
                dbsnp=self.dbsnp,
                model=self.model_bundle.joinpath("diploid_model"),
            )
        )
        first_calling_job = Job(
            Pipeline(Command(*driver.build_cmd())), "first-pass", self.cores
        )

        # Transfer annotations to the tmp vcf
        diploid_transfer_jobs: List[Job] = []
        diploid_concat_job: Optional[Job] = None
        if self.pop_vcf:
            diploid_unanno_tmp_vcf = diploid_tmp_vcf
            diploid_tmp_vcf = self.tmp_dir.joinpath(
                "out_diploid_tmp_anno.vcf.gz"
            )
            diploid_transfer_jobs, diploid_concat_job = build_transfer_jobs(
                diploid_tmp_vcf,
                self.pop_vcf,
                diploid_unanno_tmp_vcf,
                *transfer_xargs,
            )

        # DNAModelApply on the diploid VCF
        diploid_vcf = self.tmp_dir.joinpath("out_diploid.vcf.gz")
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
        )
        driver.add_algo(
            DNAModelApply(
                self.model_bundle.joinpath("diploid_model"),
                diploid_tmp_vcf,
                diploid_vcf,
            )
        )
        first_modelapply_job = Job(
            Pipeline(Command(*driver.build_cmd())),
            "first-modelapply",
            self.cores,
        )

        # Phasing and RepeatModel
        phased_bed = self.tmp_dir.joinpath("out_diploid_phased.bed")
        unphased_bed = self.tmp_dir.joinpath("out_diploid_unphased.bed")
        phased_vcf = self.tmp_dir.joinpath("out_diploid_phased.vcf.gz")
        phased_ext = self.tmp_dir.joinpath("out_diploid_phased.ext.vcf.gz")
        phased_unphased = self.tmp_dir.joinpath(
            "out_diploid_phased_unphased.vcf.gz"
        )
        phased_phased = self.tmp_dir.joinpath(
            "out_diploid_phased_phased.vcf.gz"
        )
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
            input=sample_input,
            interval=self.bed,
        )
        driver.add_algo(
            VariantPhaser(
                diploid_vcf,
                phased_vcf,
                out_bed=phased_bed,
                out_ext=phased_ext,
            )
        )
        phaser_job = Job(
            Pipeline(Command(*driver.build_cmd())), "variantphaser", self.cores
        )

        bcftools_subset_phased_job = None
        if self.tech.upper() == "ONT":
            bcftools_subset_phased_job = Job(
                Pipeline(
                    Command(
                        "bcftools",
                        "view",
                        "-T",
                        str(phased_bed),
                        str(phased_vcf),
                    ),
                    Command(
                        "sentieon",
                        "util",
                        "vcfconvert",
                        "-",
                        str(phased_phased),
                    ),
                ),
                "bcftools-subset-phased",
                0,
            )

        fai_to_bed_job = None
        if self.bed:
            bed = self.bed
        else:
            bed = self.tmp_dir.joinpath("reference.bed")
            fai_to_bed_job = Job(
                cmds.cmd_fai_to_bed(
                    pathlib.Path(str(self.reference) + ".fai"),
                    bed,
                ),
                "fai-to-bed",
                0,
            )

        bcftools_subtract_job = Job(
            cmds.cmd_bedtools_subtract(bed, phased_bed, unphased_bed),
            "bedtools-subtract",
            0,
        )

        repeatmodel_job = None
        if not self.repeat_model:
            self.repeat_model = self.tmp_dir.joinpath("out_repeat.model")
            driver = Driver(
                reference=self.reference,
                thread_count=self.cores,
                input=sample_input,
                interval=phased_bed,
                read_filter=[
                    f"PhasedReadFilter,phased_vcf={phased_ext},"
                    "phase_select=tag"
                ],  # noqa: E501
            )
            driver.add_algo(
                RepeatModel(
                    self.repeat_model,
                    phased=True,
                    read_flag_mask="drop=supplementary",
                )
            )
            repeatmodel_job = Job(
                Pipeline(Command(*driver.build_cmd())),
                "repeatmodel",
                self.cores,
            )

        bcftools_subset_unphased_job = Job(
            Pipeline(
                Command(
                    "bcftools",
                    "view",
                    "-T",
                    str(unphased_bed),
                    str(phased_vcf),
                ),
                Command(
                    "sentieon", "util", "vcfconvert", "-", str(phased_unphased)
                ),
            ),
            "bcftools-subset-unphased",
            0,
        )

        # Second pass - phased variants
        second_calling_job = set()
        for phase in (1, 2):
            hp_std_vcf = self.tmp_dir.joinpath(
                f"out_hap{phase}_nohp_tmp.vcf.gz"
            )
            hp_vcf = self.tmp_dir.joinpath(f"out_hap{phase}_tmp.vcf.gz")
            driver = Driver(
                reference=self.reference,
                thread_count=self.cores,
                input=sample_input,
                interval=phased_bed,
                read_filter=[
                    f"PhasedReadFilter,phased_vcf={phased_ext}"
                    f",phase_select={phase}"
                ],
            )

            if self.tech.upper() == "HIFI":
                # ONT doesn't do DNAscope in 2nd pass.
                driver.add_algo(
                    DNAscope(
                        hp_std_vcf,
                        dbsnp=self.dbsnp,
                        model=self.model_bundle.joinpath("haploid_model"),
                    )
                )
            driver.add_algo(
                DNAscopeHP(
                    hp_vcf,
                    dbsnp=self.dbsnp,
                    model=self.model_bundle.joinpath("haploid_hp_model"),
                    pcr_indel_model=self.repeat_model,
                )
            )
            second_calling_job.add(
                Job(
                    Pipeline(Command(*driver.build_cmd())),
                    "second-pass",
                    self.cores,
                )
            )

        kwargs: Dict[str, str] = dict()
        kwargs["gvcf_combine_py"] = str(
            files("sentieon_cli.scripts").joinpath("gvcf_combine.py")
        )
        kwargs["vcf_mod_py"] = str(
            files("sentieon_cli.scripts").joinpath("vcf_mod.py")
        )

        patch_vcfs = [
            self.tmp_dir.joinpath(f"out_hap{i}_patch.vcf.gz") for i in (1, 2)
        ]
        haploid_patch_job = Job(
            cmds.cmd_pyexec_vcf_mod_haploid_patch(
                str(patch_vcfs[0]),
                str(patch_vcfs[1]),
                f"{self.tmp_dir}/out_hap%d_%stmp.vcf.gz",
                self.tech,
                str(phased_phased),
                self.cores,
                kwargs,
            ),
            "patch",
            self.cores,
        )

        # Transfer annotations to the patched VCFs
        patch_transfer_jobs = []
        patch_concat_jobs = []
        if self.pop_vcf:
            patch_unanno_vcfs = patch_vcfs.copy()
            patch_vcfs = [
                self.tmp_dir.joinpath(f"out_hap{i}_patch_anno.vcf.gz")
                for i in (1, 2)
            ]
            for patch_unanno_vcf, patch_vcf in zip(
                patch_unanno_vcfs, patch_vcfs
            ):
                transfer_jobs, concat_job = build_transfer_jobs(
                    patch_vcf,
                    self.pop_vcf,
                    patch_unanno_vcf,
                    *transfer_xargs,
                )
                patch_transfer_jobs.append(transfer_jobs)
                patch_concat_jobs.append(concat_job)

        # apply trained model to the patched vcfs.
        hap_vcfs = [
            self.tmp_dir.joinpath(f"out_hap{i}.vcf.gz") for i in (1, 2)
        ]
        second_modelapply_job = set()
        for patch_vcf, hap_vcf in zip(patch_vcfs, hap_vcfs):
            driver = Driver(
                reference=self.reference,
                thread_count=self.cores,
            )
            driver.add_algo(
                DNAModelApply(
                    self.model_bundle.joinpath("haploid_model"),
                    patch_vcf,
                    hap_vcf,
                )
            )
            second_modelapply_job.add(
                Job(
                    Pipeline(Command(*driver.build_cmd())),
                    "second-modelapply",
                    self.cores,
                )
            )

        # Second pass - unphased regions
        diploid_unphased_hp = self.tmp_dir.joinpath(
            "out_diploid_phased_unphased_hp.vcf.gz"
        )
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
            input=sample_input,
            interval=unphased_bed,
        )
        driver.add_algo(
            DNAscopeHP(
                diploid_unphased_hp,
                dbsnp=self.dbsnp,
                model=self.model_bundle.joinpath("diploid_hp_model"),
                pcr_indel_model=self.repeat_model,
            )
        )
        calling_unphased_job = Job(
            Pipeline(Command(*driver.build_cmd())),
            "calling-unphased",
            self.cores,
        )

        # Patch DNA and DNAHP variants
        diploid_unphased_patch = self.tmp_dir.joinpath(
            "out_diploid_unphased_patch.vcf.gz"
        )
        cmd = cmds.cmd_pyexec_vcf_mod_patch(
            str(diploid_unphased_patch),
            str(phased_unphased),
            str(diploid_unphased_hp),
            self.cores,
            kwargs,
        )
        diploid_patch_job = Job(cmd, "diploid-patch", self.cores)

        # Transfer annotations to the diploid VCF
        unphased_transfer_jobs: List[Job] = []
        unphased_concat_job: Optional[Job] = None
        if self.pop_vcf:
            diploid_unphased_unanno = diploid_unphased_patch
            diploid_unphased_patch = self.tmp_dir.joinpath(
                "out_diploid_unphased_patch_anno.vcf.gz"
            )
            unphased_transfer_jobs, unphased_concat_job = build_transfer_jobs(
                diploid_unphased_patch,
                self.pop_vcf,
                diploid_unphased_unanno,
                *transfer_xargs,
            )

        # DNAModelApply on the unphased VCF
        diploid_unphased = self.tmp_dir.joinpath("out_diploid_unphased.vcf.gz")
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
        )
        driver.add_algo(
            DNAModelApply(
                self.model_bundle.joinpath("diploid_model_unphased"),
                diploid_unphased_patch,
                diploid_unphased,
            )
        )
        modelapply_unphased_job = Job(
            Pipeline(Command(*driver.build_cmd())),
            "modelapply-unphased",
            self.cores,
        )

        # merge calls to create the output
        diploid_merged_vcf = self.tmp_dir.joinpath("out_diploid_merged.vcf.gz")
        merge_out_vcf = (
            diploid_merged_vcf if self.haploid_bed else self.output_vcf
        )
        merge_job = Job(
            cmds.cmd_pyexec_vcf_mod_merge(
                str(hap_vcfs[0]),
                str(hap_vcfs[1]),
                str(diploid_unphased),
                str(phased_vcf),
                str(phased_bed),
                str(merge_out_vcf),
                self.cores,
                kwargs,
            ),
            "merge",
            self.cores,
        )

        gvcf_combine_job = None
        if self.gvcf:
            gvcf_combine_job = Job(
                cmds.cmd_pyexec_gvcf_combine(
                    self.reference,
                    str(diploid_gvcf_fn),
                    str(merge_out_vcf),
                    self.cores,
                    kwargs,
                ),
                "gvcf-combine",
                0,
            )

        haploid_calling_job = None
        haploid_patch2_job = None
        haploid_concat_job = None
        haploid_gvcf_combine_job = None
        haploid_gvcf_concat_job = None
        if self.haploid_bed:
            # Haploid variant calling
            haploid_fn = self.tmp_dir.joinpath("haploid.vcf.gz")
            haploid_gvcf_fn = self.tmp_dir.joinpath("haploid.g.vcf.gz")
            haploid_hp_fn = self.tmp_dir.joinpath("haploid_hp.vcf.gz")
            haploid_out_fn = self.tmp_dir.joinpath("haploid_patched.vcf.gz")
            driver = Driver(
                reference=self.reference,
                thread_count=self.cores,
                input=sample_input,
                interval=self.haploid_bed,
            )
            driver.add_algo(
                DNAscope(
                    haploid_fn,
                    dbsnp=self.dbsnp,
                    model=self.model_bundle.joinpath("haploid_model"),
                )
            )
            driver.add_algo(
                DNAscopeHP(
                    haploid_hp_fn,
                    dbsnp=self.dbsnp,
                    model=self.model_bundle.joinpath("haploid_hp_model"),
                    pcr_indel_model=self.repeat_model,
                )
            )
            if self.gvcf:
                driver.add_algo(
                    DNAscope(
                        haploid_gvcf_fn,
                        dbsnp=self.dbsnp,
                        emit_mode="gvcf",
                        ploidy=1,
                        model=self.model_bundle.joinpath("gvcf_model"),
                    )
                )
            haploid_calling_job = Job(
                Pipeline(Command(*driver.build_cmd())),
                "haploid-calling",
                self.cores,
            )

            haploid_patch2_job = Job(
                cmds.cmd_pyexec_vcf_mod_haploid_patch2(
                    str(haploid_out_fn),
                    str(haploid_fn),
                    str(haploid_hp_fn),
                    self.cores,
                    kwargs,
                ),
                "haploid-patch2",
                self.cores,
            )
            haploid_concat_job = Job(
                cmds.bcftools_concat(
                    self.output_vcf,
                    [diploid_merged_vcf, haploid_out_fn],
                ),
                "haploid-diploid-concat",
                0,
            )

            if self.gvcf:
                output_gvcf = pathlib.Path(
                    str(self.output_vcf).replace(".vcf.gz", ".g.vcf.gz")
                )
                diploid_gvcf = pathlib.Path(
                    str(diploid_merged_vcf).replace(".vcf.gz", ".g.vcf.gz")
                )
                haploid_gvcf = pathlib.Path(
                    str(haploid_out_fn).replace(".vcf.gz", ".g.vcf.gz")
                )
                haploid_gvcf_combine_job = Job(
                    cmds.cmd_pyexec_gvcf_combine(
                        self.reference,
                        str(haploid_gvcf_fn),
                        str(haploid_out_fn),
                        self.cores,
                        kwargs,
                    ),
                    "haploid-gvcf-combine",
                    0,
                )
                haploid_gvcf_concat_job = Job(
                    cmds.bcftools_concat(
                        output_gvcf,
                        [diploid_gvcf, haploid_gvcf],
                    ),
                    "haploid-gvcf-concat",
                    0,
                )
        return LRCallVariantsResult(
            first_calling_job,
            diploid_transfer_jobs,
            diploid_concat_job,
            first_modelapply_job,
            phaser_job,
            bcftools_subset_phased_job,
            fai_to_bed_job,
            bcftools_subtract_job,
            repeatmodel_job,
            bcftools_subset_unphased_job,
            second_calling_job,
            haploid_patch_job,
            patch_transfer_jobs,
            patch_concat_jobs,
            second_modelapply_job,
            calling_unphased_job,
            diploid_patch_job,
            unphased_transfer_jobs,
            unphased_concat_job,
            modelapply_unphased_job,
            merge_job,
            gvcf_combine_job,
            haploid_calling_job,
            haploid_patch2_job,
            haploid_concat_job,
            haploid_gvcf_combine_job,
            haploid_gvcf_concat_job,
        )

    def call_svs(
        self,
        sample_input: List[pathlib.Path],
        replace_rg: Optional[List[List[str]]] = None,
    ) -> Job:
        """
        Call SVs using Sentieon LongReadSV
        """
        if not self.model_bundle:
            self.logger.error("model_bundle is required")
            sys.exit(2)
        if not self.skip_version_check:
            for cmd, min_version in SV_MIN_VERSIONS.items():
                if not check_version(cmd, min_version):
                    sys.exit(2)

        sv_vcf = pathlib.Path(
            str(self.output_vcf).replace(".vcf.gz", ".sv.vcf.gz")
        )
        driver = Driver(
            reference=self.reference,
            thread_count=self.cores,
            replace_rg=replace_rg,
            input=sample_input,
            interval=self.bed,
        )
        driver.add_algo(
            LongReadSV(
                sv_vcf,
                self.model_bundle.joinpath("longreadsv.model"),
            )
        )
        longreadsv_job = Job(
            Pipeline(Command(*driver.build_cmd())), "LongReadSV", self.cores
        )
        return longreadsv_job

